     1	package hotel.reports;
     2	
     3	import hotel.reservations.RatePlan;
     4	import hotel.reservations.Reservation;
     5	import hotel.reservations.ReservationStore;
     6	import java.math.BigDecimal;
     7	import java.time.YearMonth;
     8	import java.util.Arrays;
     9	import java.util.List;
    10	
    11	/** The revenue of the month split by rate plan, for the management (every plan has a line, even with zero). */
    12	public final class RatePlanReport extends CsvReport<YearMonth> {
    13	
    14	    private final ReservationStore store;
    15	
    16	    public RatePlanReport(ReservationStore store) {
    17	        this.store = store;
    18	    }
    19	
    20	    private static BigDecimal sum(List<Reservation> reservations) {
    21	        return reservations.stream().map(Reservation::amountKept).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    22	    }
    23	
    24	    @Override
    25	    protected String name() {
    26	        return "rate-plans";
    27	    }
    28	
    29	    @Override
    30	    protected String header() {
    31	        return "rate_plan,reservations,amount";
    32	    }
    33	
    34	    @Override
    35	    protected List<Reservation> select(YearMonth month) {
    36	        return RevenueReport.keptMoneyIn(store, month);
    37	    }
    38	
    39	    @Override
    40	    protected List<String> rows(List<Reservation> selected) {
    41	        return Arrays.stream(RatePlan.values()).map(plan -> {
    42	            List<Reservation> ofPlan = selected.stream().filter(reservation -> reservation.ratePlan() == plan).toList();
    43	            return plan + "," + ofPlan.size() + "," + sum(ofPlan).toPlainString();
    44	        }).toList();
    45	    }
    46	
    47	    @Override
    48	    protected String total(List<Reservation> selected) {
    49	        return selected.size() + "," + sum(selected).toPlainString();
    50	    }
    51	}
