     9	
    10	/**
    11	 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
    12	 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
    13	 */
    14	public final class RevenueReport extends CsvReport<YearMonth> {
    15	
    16	    private final ReservationStore store;
    17	
    18	    public RevenueReport(ReservationStore store) {
    19	        this.store = store;
    20	    }
    21	
    22	    /** The reservations that start in the month and left money with the inn, by check-in. */
    23	    static List<Reservation> keptMoneyIn(ReservationStore store, YearMonth month) {
    24	        return store.all().stream()
    25	                .filter(reservation -> reservation.amountKept().signum() > 0)
    26	                .filter(reservation -> YearMonth.from(reservation.checkIn()).equals(month))
    27	                .sorted(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id))
    28	                .toList();
    29	    }
    30	
    31	    @Override
    32	    protected String name() {
    33	        return "revenue";
    34	    }
    35	
    36	    @Override
    37	    protected String header() {
    38	        return "reservation,room,check_in,check_out,status,amount";
    39	    }
    40	
    41	    @Override
    42	    protected List<Reservation> select(YearMonth month) {
    43	        return keptMoneyIn(store, month);
    44	    }
    45	
    46	    @Override
    47	    protected List<String> rows(List<Reservation> selected) {
    48	        return selected.stream().map(reservation -> reservation.id() + "," + reservation.roomNumber() + ","
    49	                + reservation.checkIn() + "," + reservation.checkOut() + "," + reservation.status() + ","
    50	                + reservation.amountKept().toPlainString()).toList();
    51	    }
    52	
    53	    @Override
    54	    protected String total(List<Reservation> selected) {
    55	        return selected.stream().map(Reservation::amountKept)
    56	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).toPlainString();
    57	    }
    58	}
