528	     9	/**
529	    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
530	    11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
531	    12	 * (half-even) at every step.
532	    13	 */
533	    14	public final class PriceCalculator {
534	    15	
535	    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
536	    17	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
537	    18	
538	    19	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
539	    20	        int nights = 0;
540	    21	        BigDecimal subtotal = cents(BigDecimal.ZERO);
541	    22	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
542	    23	            subtotal = subtotal.add(nightPrice(room, night));
543	    24	            nights++;
544	    25	        }
545	    26	        BigDecimal discount = switch (ratePlan) {
546	    27	            case STANDARD -> cents(BigDecimal.ZERO);
547	    28	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
548	    29	        };
549	    30	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
550	    31	    }
