    37	    public HttpApi(
    38	            Rooms rooms,
    39	            ReservationService reservations,
    40	            SentMessages sentMessages,
    41	            OccupancyReport occupancyReport,
    42	            RevenueReport revenueReport,
    43	            TourismTaxReport tourismTaxReport,
    44	            RatePlanReport ratePlanReport) {
    45	        this.rooms = rooms;
    46	        this.reservations = reservations;
    47	        this.sentMessages = sentMessages;
    48	        this.occupancyReport = occupancyReport;
    49	        this.revenueReport = revenueReport;
    50	        this.tourismTaxReport = tourismTaxReport;
    51	        this.ratePlanReport = ratePlanReport;
    52	
    53	        ObjectMapper jsonMapper = JsonMapper.builder()
    54	                .addModule(new JavaTimeModule())
    55	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    56	                .build();
    57	        this.server = Javalin.create(config -> {
    58	            config.showJavalinBanner = false;
    59	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
    60	        });
    61	        registerRoutes();
    62	        registerErrorHandling();
    63	    }
