    69	    private void registerRoutes() {
    70	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
    71	
    72	        server.post("/reservations", ctx -> {
    73	            NewReservation request = readNewReservation(ctx);
    74	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
    75	        });
    76	        server.get("/reservations/{id}", ctx ->
    77	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
    78	        server.post("/reservations/{id}/confirmation", ctx ->
    79	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
    80	        server.post("/reservations/{id}/cancellation", ctx ->
    81	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
    82	        server.post("/reservations/{id}/check-in", ctx ->
    83	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
    84	        server.post("/reservations/{id}/check-out", ctx ->
    85	                ctx.json(reservations.checkOut(reservationId(ctx))));
    86	        server.get("/reservations/{id}/document", ctx ->
    87	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
    88	
    89	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
    90	
    91	        server.get("/reports/occupancy", ctx -> {
    92	            LocalDate night = readDate(ctx);
    93	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
    94	        });
    95	        server.get("/reports/revenue", ctx -> {
    96	            YearMonth month = readMonth(ctx);
    97	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
    98	        });
    99	        server.get("/reports/tourism-tax", ctx -> {
   100	            YearMonth month = readMonth(ctx);
   101	            ctx.contentType("text/csv; charset=utf-8").result(tourismTaxReport.generate(month));
   102	        });
   103	        server.get("/reports/rate-plans", ctx -> {
   104	            YearMonth month = readMonth(ctx);
   105	            ctx.contentType("text/csv; charset=utf-8").result(ratePlanReport.generate(month));
   106	        });
   107	    }
   108	
   109	    private void registerErrorHandling() {
   110	        server.exception(HotelException.class, (exception, ctx) -> {
   111	            ctx.status(httpStatus(exception.errorCode()));
   112	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
   113	        });
   114	    }
   115	
   116	    private static int httpStatus(ErrorCode errorCode) {
   117	        return switch (errorCode) {
   118	            case INVALID_REQUEST -> 400;
   119	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
   120	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
   121	            case CAPACITY_EXCEEDED -> 422;
   122	        };
   123	    }
   124	
   125	    private static NewReservation readNewReservation(Context ctx) {
   126	        CreateReservationRequest body;
   127	        try {
   128	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   129	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   130	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
   131	        }
   132	        if (body == null
   133	                || body.roomNumber() == null
   134	                || isBlank(body.guestName())
   135	                || isBlank(body.guestEmail())
   136	                || isBlank(body.guestCpf())
   137	                || body.checkIn() == null
   138	                || body.checkOut() == null
   139	                || body.guests() == null
   140	                || body.ratePlan() == null) {
   141	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
   142	        }
   143	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
